/**
* 簡體字轉繁體字（輕量版，針對香港地名搜尋）
* 優先匹配長詞（2字以上），再匹配單字，避免「千色」被拆開轉錯
*/
function scToTc(text) {
	if (!text) return text;
	let result = text;
	const phrases = Object.keys(SC_TO_TC_MAP).filter((k) => k.length >= 2).sort((a, b) => b.length - a.length);
	for (const phrase of phrases) if (result.includes(phrase)) result = result.split(phrase).join(SC_TO_TC_MAP[phrase]);
	let final = "";
	for (let i = 0; i < result.length; i++) {
		const char = result[i];
		final += SC_TO_TC_MAP[char] ?? char;
	}
	return final;
}
/**
* 繁體字轉簡體字（輕量版）
*/
function tcToSc(text) {
	if (!text) return text;
	let result = text;
	const phrases = Object.keys(TC_TO_SC_MAP).filter((k) => k.length >= 2).sort((a, b) => b.length - a.length);
	for (const phrase of phrases) if (result.includes(phrase)) result = result.split(phrase).join(TC_TO_SC_MAP[phrase]);
	let final = "";
	for (let i = 0; i < result.length; i++) {
		const char = result[i];
		final += TC_TO_SC_MAP[char] ?? char;
	}
	return final;
}
